import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.UsESEDQP.js";const u=JSON.parse('{"title":"Feeds Integration","description":"Bridge RSS and Atom feeds into Matrix rooms","frontmatter":{"title":"Feeds Integration","description":"Bridge RSS and Atom feeds into Matrix rooms","audience":["user","operator"],"integration":"feeds","status":"current"},"headers":[],"relativePath":"integrations/feeds.md","filePath":"integrations/feeds.md","lastUpdated":1775248363000}'),o={name:"integrations/feeds.md"};function n(r,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="rss-atom-feeds" tabindex="-1">RSS/Atom Feeds <a class="header-anchor" href="#rss-atom-feeds" aria-label="Permalink to &quot;RSS/Atom Feeds&quot;">​</a></h1><p>Hookshot polls RSS and Atom feeds and posts new entries to Matrix rooms. No webhooks needed — hookshot fetches feeds on a configurable interval.</p><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Supported</th></tr></thead><tbody><tr><td>Receive notifications</td><td>Yes — new feed entries</td></tr><tr><td>Bot commands</td><td>Via <code>!hookshot feed</code></td></tr><tr><td>Authentication</td><td>None (public feeds only)</td></tr><tr><td>Custom templates</td><td>Yes — token-based message templates</td></tr><tr><td>Error notifications</td><td>Optional — notify on fetch failures</td></tr><tr><td>Persistence</td><td>Requires Redis to avoid re-posting after restart</td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">feeds</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">  enabled</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> true</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">  pollIntervalSeconds</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> 600</span><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">    # Check feeds every 10 minutes</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">  pollTimeoutSeconds</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> 30</span><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">      # Timeout per feed fetch</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">  pollConcurrency</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> 4</span><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">          # Parallel feed fetches</span></span></code></pre></div><p>Feeds are parsed in Rust for performance. Supports ETag/Last-Modified caching.</p><p><strong>Redis required for persistence:</strong> Without Redis, hookshot runs an &quot;initial sync&quot; on each startup and treats all existing entries as already seen. Previously seen entries are lost on restart, which may cause re-posting.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">cache</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">  redisUri</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> &quot;redis://localhost:6379&quot;</span></span></code></pre></div><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><h3 id="add-a-feed-to-a-room" tabindex="-1">Add a feed to a room <a class="header-anchor" href="#add-a-feed-to-a-room" aria-label="Permalink to &quot;Add a feed to a room&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>!hookshot feed https://blog.example.com/rss.xml</span></span></code></pre></div><p>With a custom label and template:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>!hookshot feed https://blog.example.com/rss.xml &quot;Team Blog&quot; &quot;📰 $TITLE by $AUTHOR: $LINK&quot;</span></span></code></pre></div><h3 id="list-subscribed-feeds" tabindex="-1">List subscribed feeds <a class="header-anchor" href="#list-subscribed-feeds" aria-label="Permalink to &quot;List subscribed feeds&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>!hookshot feed list</span></span>
<span class="line"><span>!hookshot feed list json    # JSON format</span></span>
<span class="line"><span>!hookshot feed list yaml    # YAML format</span></span></code></pre></div><h3 id="remove-a-feed" tabindex="-1">Remove a feed <a class="header-anchor" href="#remove-a-feed" aria-label="Permalink to &quot;Remove a feed&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>!hookshot feed remove https://blog.example.com/rss.xml</span></span></code></pre></div><h2 id="message-templates" tabindex="-1">Message templates <a class="header-anchor" href="#message-templates" aria-label="Permalink to &quot;Message templates&quot;">​</a></h2><p>Customize how feed entries appear in Matrix. Available tokens:</p><table tabindex="0"><thead><tr><th>Token</th><th>Description</th></tr></thead><tbody><tr><td><code>$FEEDNAME</code></td><td>Feed label, title, or URL</td></tr><tr><td><code>$FEEDURL</code></td><td>Feed URL</td></tr><tr><td><code>$FEEDTITLE</code></td><td>Feed title from the feed itself</td></tr><tr><td><code>$TITLE</code></td><td>Entry title</td></tr><tr><td><code>$URL</code></td><td>Entry URL</td></tr><tr><td><code>$LINK</code></td><td>Entry as markdown link: <code>[$TITLE]($URL)</code></td></tr><tr><td><code>$AUTHOR</code></td><td>Entry author</td></tr><tr><td><code>$DATE</code></td><td>Publication date</td></tr><tr><td><code>$SUMMARY</code></td><td>Entry summary (truncated to 512 chars)</td></tr></tbody></table><p>Default template: <code>New post in $FEEDNAME: $LINK</code></p><h2 id="connection-options" tabindex="-1">Connection options <a class="header-anchor" href="#connection-options" aria-label="Permalink to &quot;Connection options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>url</code></td><td>string</td><td>required</td><td>Feed URL (RSS or Atom)</td></tr><tr><td><code>label</code></td><td>string</td><td>feed title</td><td>Display name for the feed</td></tr><tr><td><code>template</code></td><td>string</td><td>see above</td><td>Message template (max 1024 chars)</td></tr><tr><td><code>notifyOnFailure</code></td><td>boolean</td><td>false</td><td>Send error message when fetch fails</td></tr></tbody></table><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li><code>FeedReader</code> service polls each feed URL at <code>pollIntervalSeconds</code> intervals</li><li>Rust feed parser fetches and parses the feed (RSS 2.0 or Atom 1.0)</li><li>New entries (not previously seen) produce <code>feed.entry</code> events on the message queue</li><li><code>FeedConnection.handleFeedEntry()</code> formats the message using the template</li><li>Message sent to the Matrix room</li></ol><p>Each feed is polled once regardless of how many rooms subscribe to it. Entry deduplication uses MD5 hashing.</p><h2 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;Diagnostics&quot;">​</a></h2><p>The provisioning API returns the last 5 poll results per feed, including timestamps and error messages. This helps diagnose failing feeds.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>Public feeds only — no authentication for feed fetching</li><li>No content filtering — all new entries are posted</li><li>MD5 used for deduplication (not for security)</li><li>Without Redis, feed state is lost on restart</li><li>Summary is truncated to 512 characters</li><li>Entries are not sorted by date before posting — they arrive in feed order</li><li>Message retry: 5 attempts with 5-second intervals on send failure</li></ul><h2 id="upstream-references" tabindex="-1">Upstream references <a class="header-anchor" href="#upstream-references" aria-label="Permalink to &quot;Upstream references&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>URL</th></tr></thead><tbody><tr><td>RSS 2.0 specification</td><td><a href="https://www.rssboard.org/rss-specification" target="_blank" rel="noreferrer">rssboard.org/rss-specification</a></td></tr><tr><td>Atom specification</td><td><a href="https://tools.ietf.org/html/rfc4287" target="_blank" rel="noreferrer">RFC 4287</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><strong>Concepts:</strong> <a href="./../understand/event-lifecycle">Event Lifecycle</a> · <a href="./../understand/integration-model">Integration Model</a></p><p><strong>Integrations:</strong> <a href="./overview">Overview</a> · <a href="./generic-webhooks">Generic Webhooks</a> — Alternative for push-based sources</p><p><strong>Reference:</strong> <a href="./../reference/event-types">Event Types</a> · <a href="./../reference/bot-commands#admin-commands-dm-with-bot">Bot Commands</a></p><p><strong>Operator:</strong> <a href="./../guides/operator/configuration#cache-optional">Configuration: Cache</a> — Redis for persistence · <a href="./../guides/operator/service-bots">Configuration: Service bots</a> — Dedicated feeds bot · <a href="./../guides/operator/monitoring">Monitoring</a></p><p><strong>Get started:</strong> <a href="./../get-started/quickstart">Quickstart</a></p><p><strong>Troubleshooting:</strong> <a href="./../troubleshooting/connection-issues">Connection Issues</a> · <a href="./../troubleshooting/common-errors#feed-errors">Common Errors</a></p>`,40)])])}const f=t(o,[["render",n]]);export{u as __pageData,f as default};
